/bin/zsh -lc "python3 - <<'PY'
import os,re
from pathlib import Path
for p in [Path.home()/'.codex/config.toml',Path('<home>/Library/Application Support/orca/codex-accounts/<run-id>/home/config.toml')]:
 if p.exists():
  print(str(p))
  for line in p.read_text().splitlines():
   if re.match(r'"'^(model|model_reasoning_effort|profile)'"\\s*=',line):print(line)
print('Selected environment:',{k:v for k,v in os.environ.items() if k in ['CODEX_MODEL','CODEX_MODEL_REASONING_EFFORT','OPENAI_MODEL','CODEX_HOME']})
PY"

